// register). Same as the reference, but with a named block of the
// transition logic extracted.
module TopModule(input in, input [1:0] state, output [1:0] next_state,
                 output reg out);
    wire [1:0] ns1;
    wire [1:0] ns2;
    assign ns1 = (in == 0) ? 2'b00 : 2'b01;
    assign ns2 = (in == 0) ? 2'b10 : 2'b01;
    always @(*) begin
        case (state)
            2'b00: begin next_state = ns1; out = 1'b0; end
            2'b01: begin next_state = ns2; out = 1'b0; end
            2'b10: begin next_state = ns1; out = 1'b0; end
            2'b11: begin next_state = ns2; out = 1'b1; end
        endcase
    end
endmodule

