// Moore state machine with one input, one output, and four states.
// State transition logic (the combinational logic portion) only.
// Compute the next_state and output (out) based on the state
// transition table.
module TopModule(input in, input [1:0] state, output [1:0] next_state, output reg out);
    always @(*) begin
        case (state)
            2'b00: begin next_state = 2'b00; out = 1'b0; end
            2'b01: begin next_state = in ? 2'b01 : 2'b01; out = 1'b0; end
            2'b10: begin next_state = in ? 2'b11 : 2'b00; out = 1'b0; end
            2'b11: begin next_state = in ? 2'b01 : 2'b10; out = 1'b1; end
        endcase
    end
endmodule

// Moore state machine: one input, one output, explicit next state
// (state register plus combinational next state function).
module TopModule(input in, input [1:0] state, output [1:0] next_state, output reg out);
  reg [1:0] ns;
  always @(*) begin
    case (state)
      2'b00: begin out = 1'b0; ns = in ? 2'b01 : 2'b00; end
      2'b01: begin out = 1'b0; ns = in ? 2'b10 : 2'b01; end
      2'b10: begin out = 1'b0; ns = in ? 2'b00 : 2'b10; end
      2'b11: begin out = 1'b1; ns = in ? 2'b10 : 2'b01; end
    endcase
  end
  always @(posedge clk) next_state <= ns;
endmodule

