            2'b01: begin ns = 2'b01; o = 1'b0; end
            2'b10: begin ns = 2'b10; o = 1'b0; end
            2'b11: begin ns = 2'b01; o = 1'b1; end
        endcase
    end
    assign next_state = ns;
    assign out = o;
